---@meta
---@module 'lib.nvim.git.@types'

---@class Lib.Git
---@field in_git_repo fun(opts?: Lib.Git.Opts, git_cmd?: string): boolean # Check if the cwd (or `opts.dir`) is inside a Git work-tree.
---@field repo_root fun(opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Get the absolute path to the repository root.
---@field current_branch fun(opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Get the current branch name. Returns nil in detached HEAD state.
---@field checkout fun(name: string, opts?: Lib.Git.Opts, git_cmd?: string): boolean, string|nil # Check out an existing local branch or other revision (`git checkout <name>`). Returns ok + git's own stderr on failure.
---@field is_detached_head fun(opts?: Lib.Git.Opts, git_cmd?: string): boolean # Check whether the repository is in a detached HEAD state.
---@field is_dirty fun(opts?: Lib.Git.Opts, git_cmd?: string): boolean # Check whether the working tree has uncommitted changes.
---@field is_tracked fun(path: string, opts?: Lib.Git.Opts, git_cmd?: string): boolean # Check whether the given path is tracked by Git.
---@field is_skip_worktree fun(path: string, opts?: Lib.Git.Opts, git_cmd?: string): boolean|nil, string|nil # Whether a tracked file is marked `skip-worktree` (`ls-files -v` tag `S`/`s`); nil + err when unknown (untracked, git failed, invalid path).
---@field set_skip_worktree fun(path: string, on: boolean, opts?: Lib.Git.Opts, git_cmd?: string): boolean, string|nil # `update-index --[no-]skip-worktree`; ok + git's stderr on failure.
---@field toggle_skip_worktree fun(path: string, opts?: Lib.Git.Opts, git_cmd?: string): boolean|nil, string|nil # Flip the mark; returns the state after the flip, nil + err on failure.
---@field upstream fun(opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Get the upstream branch of the current branch.
---@field ahead_behind fun(opts?: Lib.Git.Opts, git_cmd?: string): (boolean, boolean) # Check whether the current branch is ahead or behind its upstream.
---@field head_hash fun(opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Get the full hash of HEAD.
---@field tree_hash fun(opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Get the tree id of HEAD (`HEAD^{tree}`); stable across message-only amends.
---@field head_short_hash fun(opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Get the short hash of HEAD.
---@field describe fun(opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Nearest reachable tag (`git describe --tags`), or the short hash if there is none (`--always`).
---@field info fun(dir: string, git_cmd?: string): { branch: string|nil, version: string|nil, commit: string|nil } # One-shot repo identity snapshot for an arbitrary directory (`git -C <dir> ...`).
---@field refs fun(dir?: string, opts?: { branches?: boolean, remotes?: boolean, tags?: boolean, limit?: integer }, git_cmd?: string): string[] # Named revisions (local branches, remote branches, tags), each group most-recent-commit first, deduplicated. Built for <Tab>-completing a revision argument.
---@field parse_status fun(raw: string): Lib.Git.StatusMap # Pure parser for `git status --porcelain -z` output (path -> {code, orig_path}); renames/copies are keyed by their new path.
---@field status_porcelain fun(opts?: Lib.Git.Opts, git_cmd?: string): Lib.Git.StatusMap|nil, string|nil # Working-tree status as a path -> {code, orig_path} map (`-z`, so paths with spaces/non-ASCII are exact). nil + err only on a git failure; a clean tree is `{}`.
---@field status_porcelain_async fun(opts: Lib.Git.Opts|nil, on_done: fun(map: Lib.Git.StatusMap|nil, err: string|nil), git_cmd?: string): { stop: fun() } # Async counterpart to status_porcelain -- prefer on a repeated/automatic trigger.
---@field remote_url fun(remote?: string, opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Get a configured remote's URL (defaults to "origin").
---@field relative_path fun(path: string, opts?: Lib.Git.Opts, git_cmd?: string): string|nil # Resolve a tracked path's repository-relative form via `git ls-files --full-name`.
---@field current_ref fun(dir: string, git_cmd?: string): string|nil # The branch name, or (detached HEAD) the short commit hash, for an explicit directory. Two git calls, not three -- prefer this over `info(dir)` when the tag/version field isn't needed.
---@field remote_url_fast fun(remote?: string, opts?: Lib.Git.Opts, git_cmd?: string): string|nil # `remote_url` read from the repository's config file, no process in the usual case; falls back to git for URL rewrites, includes and other cases the file cannot answer exactly.
---@field current_ref_fast fun(dir?: string, git_cmd?: string): string|nil # `current_ref` read from the worktree's HEAD file, no process for a branch; a detached HEAD asks git once per HEAD content.
---@field show fun(rev: string, path: string, opts?: Lib.Git.Opts, git_cmd?: string): string|nil, string|nil # A file's content at a revision (`git show <rev>:<path>`), byte for byte (CRLF and binary intact); an empty file is `""`. `rev` may be `""` (the index) or `":1"`/`":2"`/`":3"` (merge stages). nil + err on failure.
---@field show_async fun(rev: string, path: string, opts: Lib.Git.Opts|nil, on_done: fun(content: string|nil, err: string|nil), git_cmd?: string): { stop: fun() } # Async counterpart to show.
---@field blame_porcelain fun(path: string, opts?: { first?: integer, last?: integer, dir?: string }, git_cmd?: string): Lib.Git.BlameEntry[]|nil, string|nil # Blame a file (or a line range) via `git blame --porcelain`. nil only on a git-invocation failure -- an empty file is `{}`.
---@field blame_porcelain_async fun(path: string, opts: { first?: integer, last?: integer, dir?: string }|nil, on_done: fun(entries: Lib.Git.BlameEntry[]|nil, err: string|nil), git_cmd?: string): { stop: fun() } # Async counterpart to blame_porcelain -- prefer on a repeated/automatic trigger (e.g. CursorHold).
---@field clear_line_diff fun(ns:integer):fun(buf:integer):nil # Create a buffer-scoped function that clears all virtual text in the given namespace. This function binds the namespace once and returns a callback suitable for autocmd usage.
---@field run fun(args: string[], opts?: Lib.Git.RunOpts, git_cmd?: string): Lib.Git.RunResult # Run `git <args>` and report exit code, both streams and whether it timed out. The generic runner; blocks the caller.
---@field run_async fun(args: string[], opts: Lib.Git.RunOpts|nil, on_done: fun(result: Lib.Git.RunResult), git_cmd?: string): { stop: fun() } # Async counterpart to run.
---@field parse_log fun(raw: string, opts?: { left_right?: boolean, name_status?: boolean }): Lib.Git.LogEntry[]|nil, string|nil # Pure parser for the NUL-separated `git log` output that `log` runs; strict, an unexpected shape is an error.
---@field log fun(range?: string, opts?: Lib.Git.LogOpts, git_cmd?: string): Lib.Git.LogEntry[]|nil, string|nil # The commits of a revision range, parsed, in one process (bodies and, with `name_status`, changed files included). An empty range is `{}`; nil + err when git failed.
---@field log_async fun(range: string|nil, opts: Lib.Git.LogOpts|nil, on_done: fun(entries: Lib.Git.LogEntry[]|nil, err: string|nil), git_cmd?: string): { stop: fun() } # Async counterpart to log.
---@field rev_parse fun(rev: string, opts?: Lib.Git.RevParseOpts, git_cmd?: string): string|nil, string|nil # Resolve a revision to its full object name (`git rev-parse --verify`); `short` and `commit` options.
---@field merge_base fun(a: string, b: string, opts?: Lib.Git.RunOpts, git_cmd?: string): string|nil, string|nil # The best common ancestor of two revisions; nil + "no common ancestor" for unrelated histories.
---@field is_ancestor fun(ancestor: string, rev: string, opts?: Lib.Git.RunOpts, git_cmd?: string): boolean|nil, string|nil # Whether `ancestor` is reachable from `rev`; nil + err when git could not tell.
---@field rev_parse_async fun(rev: string, opts: Lib.Git.RevParseOpts|nil, on_done: fun(sha: string|nil, err: string|nil), git_cmd?: string): { stop: fun() } # Async counterpart to rev_parse.
---@field merge_base_async fun(a: string, b: string, opts: Lib.Git.RunOpts|nil, on_done: fun(sha: string|nil, err: string|nil), git_cmd?: string): { stop: fun() } # Async counterpart to merge_base.
---@field is_ancestor_async fun(ancestor: string, rev: string, opts: Lib.Git.RunOpts|nil, on_done: fun(answer: boolean|nil, err: string|nil), git_cmd?: string): { stop: fun() } # Async counterpart to is_ancestor.
---@field tags fun(opts?: Lib.Git.TagsOpts, git_cmd?: string): Lib.Git.Tag[]|nil, string|nil # Tags with annotation flag, peeled commit, creator time and subject, in one process; `merged`/`no_merged` select the tags of a range.
---@field tags_async fun(opts: Lib.Git.TagsOpts|nil, on_done: fun(tags: Lib.Git.Tag[]|nil, err: string|nil), git_cmd?: string): { stop: fun() } # Async counterpart to tags.
---@field fetch_async fun(opts: Lib.Git.NetOpts|nil, on_done: fun(ok: boolean, err: string|nil, changed: boolean|nil), git_cmd?: string): { stop: fun() } # `git fetch --all --prune`; `changed`: a remote-tracking ref moved. Runs with `GIT_TERMINAL_PROMPT=0` and kills git after 120 s unless `opts` says otherwise.
---@field pull_async fun(opts: Lib.Git.NetOpts|nil, on_done: fun(ok: boolean, err: string|nil, changed: boolean|nil), git_cmd?: string): { stop: fun() } # `git pull --ff-only`; `changed`: `HEAD` moved. Same `GIT_TERMINAL_PROMPT=0` and 120 s defaults for the pull and for the two `HEAD` reads around it. Silent once `stop()` was called.
---@field push_async fun(opts: Lib.Git.NetOpts|nil, on_done: fun(ok: boolean, err: string|nil), git_cmd?: string): { stop: fun() } # `git push`. Runs with `GIT_TERMINAL_PROMPT=0` and kills git after 120 s unless `opts` says otherwise.
---@field update_async fun(opts: Lib.Git.NetOpts|nil, on_done: fun(ok: boolean, err: string|nil, changed: boolean|nil), git_cmd?: string): { stop: fun() } # `fetch_async`, then `pull_async` (the pull's `changed`), both with the same `opts`. Silent once `stop()` was called.
---@field LOG_FORMAT string # The `--format=` argument `log` passes, for a caller that runs `git log -z` itself and feeds `parse_log`.

-- Lib.Git.Opts, Lib.Git.StatusEntry/StatusMap and Lib.Git.BlameEntry are
-- declared in git/init.lua, right above the functions that use them -- not
-- duplicated here. The types of the run/log/tags section live below.

---Options of the network verbs (`fetch_async`, `pull_async`, `push_async`, `update_async`):
---`Lib.Git.Opts` (`dir`) plus the environment and the deadline of each git process.
---@class Lib.Git.NetOpts : Lib.Git.Opts
---@field env? table<string, string> Extra environment variables; wins over the default `GIT_TERMINAL_PROMPT=0`.
---@field timeout_ms? integer|false Deadline of each git process in milliseconds (default 120000); `false` waits forever.

---Options of every function that runs `git` and reports a result: `Lib.Git.Opts`
---(`dir`) plus a timeout, an environment and the knobs a caller reading someone
---else's repository needs.
---@class Lib.Git.RunOpts : Lib.Git.Opts
---@field timeout_ms? integer Kill git after this many milliseconds; the result is then `timed_out` (exit code 124). On POSIX the whole process group is killed, on Windows the whole process tree, so a transport helper such as `git-remote-https` does not outlive the deadline. The async runner answers at the deadline plus a short grace even if a descendant keeps the pipes open.
---@field max_output_bytes? integer Stop git once its stdout exceeds this many bytes: the result is then `ok = false`, `code = 125` and `stderr` says why. Reading a repository somebody else wrote, one commit with a huge message makes `log` print gigabytes from a tiny object; without a cap all of it ends up in memory.
---@field env? table<string, string> Extra environment variables, merged over the inherited ones.
---@field no_lazy_fetch? boolean Never fetch missing objects of a partial (blobless) clone: sets `GIT_NO_LAZY_FETCH=1` (git 2.44+, the primary lock), `GIT_ALLOW_PROTOCOL=none` (every git since 2.10; it beats a `protocol.<name>.allow` in the repository's or the user's config, which a plain `protocol.allow=never` does not) **and** passes `-c protocol.allow=never`. git then fails on a missing object instead of silently fetching it -- no network, no write into the clone. The same switch blocks every transport, so a command that really needs the network (`fetch`) fails under it.
---@field read_only? boolean Add `--no-optional-locks`, so the call never takes the index lock. `run`/`run_async` only; the functions that only read (`log`, `rev_parse`, ...) always set it.
---@field input? string Standard input. `run`/`run_async` only.
---@field binary? boolean Deliver stdout byte for byte (no `\r\n` rewriting). `run`/`run_async` only; `log` and `tags` always do.

---Options of the network verbs `fetch_async`, `pull_async`, `push_async` and `update_async`:
---`Lib.Git.RunOpts` with one difference, `timeout_ms` (below). These verbs use `dir`, `env` and
---`timeout_ms`; `no_lazy_fetch` is honoured too, as `-c protocol.allow=never`, which blocks every
---transport, so a verb that needs the network fails under it; `max_output_bytes`, `read_only`,
---`input` and `binary` have no effect on them. Unless `env` says otherwise they run with
---`GIT_TERMINAL_PROMPT=0` (git fails instead of asking on a terminal Neovim cannot type into), and
---every git process of a call gets the same `env` and `timeout_ms`: the fetch of `update_async`, the
---pull, and the two `rev-parse HEAD` reads around the pull of `pull_async`/`update_async`.
---@class Lib.Git.NetOpts : Lib.Git.RunOpts
---@field timeout_ms? integer|false Kill each git process of the call after this many milliseconds; the default is `120000`, `false` waits forever. A deadline that was hit is a failure whose `err` names it ("git fetch timed out after 120s", "... after 1.5s", "... after 500 ms"). The kill reaches the whole process group on POSIX and the whole process tree on Windows.

---What `run` and `run_async` report -- `lib.nvim.cross.run_argv`'s result: `ok` (exit code 0
---and not killed by a signal), `code` (`124` after `opts.timeout_ms`, `128 + signal` when a
---signal killed git, `-1` when git could not be started at all), `signal`, `stdout`,
---`stderr` (`nil` only on Neovim without `vim.system`, which cannot separate the streams;
---for a spawn failure it is the reason) and `timed_out`.
---@class Lib.Git.RunResult : Lib.RunArgv.Result

---Options of `log` and `log_async`.
---@class Lib.Git.LogOpts : Lib.Git.RunOpts
---@field name_status? boolean Add the changed files of every commit (`--name-status --no-renames`) as `entry.files`. Renames are reported as a delete plus an add: rename detection needs file contents and breaks in a blobless clone.
---@field left_right? boolean Set `entry.side` for a symmetric range `A...B`.
---@field reverse? boolean Oldest first (`--reverse`).
---@field topo_order? boolean Never show a commit before all its children (`--topo-order`).
---@field no_merges? boolean Skip merge commits.
---@field first_parent? boolean Follow only the first parent of each merge.
---@field max_count? integer At most this many commits (`--max-count`).
---@field skip? integer Skip this many commits first (`--skip`).
---@field paths? string[] Only commits touching these paths (after `--`). Taken **literally** (each is passed as `:(literal)<path>`): `a[1].txt` is that file, not a glob.
---@field pathspecs? boolean Read `paths` as git pathspecs instead (globs, `:(exclude)` and other magic).

---One commit, as `log` returns it.
---@class Lib.Git.LogEntry
---@field sha string Full object name (40 or, with SHA-256, 64 hex digits).
---@field parents string[] Parent object names; empty for a root commit, two or more for a merge.
---@field author string
---@field email string
---@field author_time integer|nil Unix time of the author date.
---@field commit_time integer|nil Unix time of the *committer* date -- the one that places the commit in the history.
---@field refs string[] Git's decoration list (`%D`) for the commit: `"HEAD -> main"`, `"tag: v1.0"`, `"origin/main"`. It also holds the pseudo-decorations `"grafted"` (the boundary commit of a shallow clone) and `"replaced"`, which cannot be told from a branch of that name.
---@field subject string First line of the message, `\r\n` normalised.
---@field body string The rest of the message, trailing whitespace removed, `\r\n` normalised.
---@field side? "<"|">"|"-" With `left_right`: `>` only reachable from the right of `A...B`, `<` only from the left, `-` a boundary commit.
---@field files? Lib.Git.LogFile[] With `name_status`: the changed files. Empty for an empty commit and -- unless `first_parent` is set, which diffs a merge against its first parent -- for a merge.

---One changed file of a commit.
---@class Lib.Git.LogFile
---@field status string Single-letter git status (`A`dded, `M`odified, `D`eleted, `T`ype change, ...), with a similarity score for `R`/`C` (`R100`).
---@field path string The path after the change; paths are exact (`-z`), never C-quoted.
---@field orig_path? string The source of an `R`/`C`.

---Options of `rev_parse`.
---@class Lib.Git.RevParseOpts : Lib.Git.RunOpts
---@field short? boolean|integer Abbreviate the result (`true`: git's default length, a number: that many digits -- git never goes below 4).
---@field commit? boolean Peel to a commit (`<rev>^{commit}`): a tag name gives the commit it points to, not the tag object.

---Options of `tags`.
---@class Lib.Git.TagsOpts : Lib.Git.RunOpts
---@field merged? string Only tags reachable from this revision.
---@field no_merged? string Only tags *not* reachable from this revision.
---@field pattern? string A glob on the tag name (`"v1.*"`).
---@field limit? integer At most this many tags (`0` is no tags, not "unlimited" as for git's own `--count=0`).
---@field sort? "newest"|"oldest"|"version" By creator date, newest first (default); oldest first; by version number, highest first.

---One tag, as `tags` returns it.
---@class Lib.Git.Tag
---@field name string
---@field sha string The object the tag points to, peeled for an annotated tag -- a commit when `commit` is true.
---@field object string The tag's own object name -- equal to `sha` for a lightweight tag.
---@field annotated boolean A tag object (with a message and tagger) rather than a bare ref.
---@field commit boolean `sha` is a commit. False for a tag on a tree or a blob (git/git has some), whose `sha` is no use in `log` or a compare URL.
---@field time integer|nil Creator time: the tagger date of an annotated tag, the commit date of a lightweight one (`nil` for a lightweight tag on a tree or blob, and for a date that is not a plausible Unix time).
---@field subject string First line of the tag message (annotated) or of the commit (lightweight).

return {}
